/audit-output/evidence/procself_readlink.content:
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

ssize_t readlink(const char *path, char *buffer, size_t size) {
  static readlink_fn real_readlink = NULL;
  char blocked[64];
  if (real_readlink == NULL) {
    real_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
  }
  snprintf(blocked, sizeof(blocked), "/proc/%ld/exe", (long)getpid());
  if (strcmp(path, blocked) == 0) {
    path = "/proc/self/exe";
  }
  return real_readlink(path, buffer, size);
}

/audit-output/evidence/procfs_path_probe.content:
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

static void probe(const char *path) {
  char buffer[PATH_MAX];
  errno = 0;
  ssize_t count = readlink(path, buffer, sizeof(buffer) - 1);
  if (count < 0) {
    printf("%s: readlink failed: errno=%d (%s)\n", path, errno, strerror(errno));
  } else {
    buffer[count] = '\0';
    printf("%s: %s\n", path, buffer);
  }
}

int main(void) {
  char pid_path[64];
  snprintf(pid_path, sizeof(pid_path), "/proc/%ld/exe", (long)getpid());
  probe("/proc/self/exe");
  probe(pid_path);
  return 0;
}

